htmlform.script:







// Live alert-highlighting for the numeric obs fields.
// The id given on each obs tag is passed through to the rendered
// input by HTML Form Entry, so we can hook directly into it here.
// This ONLY toggles a CSS class -- it never changes the submitted value,
// so obs are still saved against their original conceptId as normal.
(function () {
  var rules = [
    { id: 'fhrId',       test: function (v) { return v < 110 || v >= 160; } },
    { id: 'pulseId',     test: function (v) { return v < 60  || v >= 120; } },
    { id: 'respId',      test: function (v) { return v < 12  || v >= 20;  } },
    { id: 'sysbpId',     test: function (v) { return v < 80  || v >= 140; } },
    { id: 'diabpId',     test: function (v) { return v >= 90; } },
    { id: 'tempId',      test: function (v) { return v < 35.0 || v >= 37.5; } },
    { id: 'contrCountId',test: function (v) { return v &lt;= 2  || v > 5;  } },
    { id: 'contrDurId',  test: function (v) { return v < 20  || v > 60; } }
  ];

  function wire(rule) {
    var el = document.getElementById(rule.id);
    if (!el) { return; }
    var check = function () {
      var v = parseFloat(el.value);
      var bad = el.value !== '' &amp;&amp; !isNaN(v) &amp;&amp; rule.test(v);
      if (bad) {
        el.classList.add('alert-value');
      } else {
        el.classList.remove('alert-value');
      }
    };
    el.addEventListener('input', check);
    el.addEventListener('change', check);
    check();
  }

  // Run after the form widgets have rendered.
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      rules.forEach(wire);
    });
  } else {
    rules.forEach(wire);
  }
})();
